% Extraterrestrial Radiation for 365 days
% Define solar constant
Gsc = 1367; % W/m^2

% Day numbers from 1 to 365
n = 1:365;

% Compute B in degrees
B = (n - 1) .* (360/365);

% Equation 1 - Simple formula
Gon1 = Gsc .* (1 + 0.033 .* cosd(360 .* n ./ 365));

% Equation 2 - More accurate formula
Gon2 = Gsc .* (1.000110 + 0.034221.*cosd(B) + 0.001280.*sind(B) ...
       + 0.000719.*cosd(2.*B) + 0.000077.*sind(2.*B));

% Plot both equations
figure;
plot(n, Gon1, 'b-', 'LineWidth', 1.5);
hold on;
plot(n, Gon2, 'r--', 'LineWidth', 1.5);
xlabel('Day Number (n)');
ylabel('Gon (W/m^2)');
title('Extraterrestrial Radiation for 365 Days');
legend('Equation 1 (Simple)', 'Equation 2 (Accurate)');
grid on;

% Define polynomials as coefficient vectors (highest power first)
P1 = [3, 15, 0, -10, -3, 15, -40];  % degree 6
P2_orig = [3, 0, -2, -6];            % degree 3 original

% Pad P2 to match degree of P1 (add leading zeros)
P2 = [0, 0, 0, 3, 0, -2, -6];       % padded to degree 6

% i. Addition
P_add = P1 + P2;
disp('P1 + P2 ='); disp(P_add);

% i. Subtraction
P_sub = P1 - P2;
disp('P1 - P2 ='); disp(P_sub);

% i. Multiplication
P_mul = conv(P1, P2_orig);
disp('P1 * P2 ='); disp(P_mul);

% i. Division
[Q, R] = deconv(P1, P2_orig);
disp('P1 / P2, Quotient ='); disp(Q);
disp('Remainder ='); disp(R);

% ii. Evaluate at given points
val_P1_3 = polyval(P1, 3);
fprintf('P1(3) = %g\n', val_P1_3);

val_P2_6 = polyval(P2_orig, 6);
fprintf('P2(6) = %g\n', val_P2_6);

% iii. Roots
roots_P1 = roots(P1);
disp('Roots of P1:'); disp(roots_P1);

roots_P2 = roots(P2_orig);
disp('Roots of P2:'); disp(roots_P2);

% Define complex numbers
Z1 = 2 + 3.5i;
Z2 = 1 + 1.5i;

% i. Polar representation of Z1
mag_Z1 = abs(Z1);         % magnitude
phase_Z1 = angle(Z1);     % phase in radians
phase_deg = rad2deg(phase_Z1); % convert to degrees

fprintf('|Z1| = %.4f\n', mag_Z1);
fprintf('Angle of Z1 = %.4f rad = %.4f deg\n', phase_Z1, phase_deg);
fprintf('Polar form: Z1 = %.4f * e^(j * %.4f)\n', mag_Z1, phase_Z1);

% ii. Addition
Z_add = Z1 + Z2;
fprintf('Z1 + Z2 = %.4f + %.4fi\n', real(Z_add), imag(Z_add));

% ii. Multiplication
Z_mul = Z1 * Z2;
fprintf('Z1 * Z2 = %.4f + %.4fi\n', real(Z_mul), imag(Z_mul));

% Viscosity curve fitting
% Temperature in Celsius
T_C = [-20, 0, 40, 100, 200, 300, 400, 500];

% Viscosity in Ns/m^2
mu = [1.63, 1.71, 1.87, 2.17, 2.53, 2.98, 3.32, 3.64] * 1e-5;

% Convert temperature to Kelvin
T = T_C + 273.15;

% Linearize: T^(3/2)/mu = T/C + S/C
Y = T.^(3/2) ./ mu;   % dependent variable
X = T;                 % independent variable

% Fit first-order polynomial Y = m*X + b
coeffs = polyfit(X, Y, 1);
m = coeffs(1);  % slope = 1/C
b = coeffs(2);  % intercept = S/C

% Calculate C and S
C = 1 / m;
S = b * C;
fprintf('C = %.6e\n', C);
fprintf('S = %.4f\n', S);

% Generate smooth curve for plotting
T_fit = linspace(min(T), max(T), 200);
mu_fit = C .* T_fit.^(3/2) ./ (T_fit + S);

% Plot
figure;
plot(T_C, mu*1e5, 'ro', 'MarkerSize', 8, 'LineWidth', 2); % data markers
hold on;
plot(T_fit - 273.15, mu_fit*1e5, 'b-', 'LineWidth', 2);  % fitted curve
xlabel('Temperature (°C)');
ylabel('Viscosity (x10^{-5} Ns/m^2)');
title('Viscosity of Air vs Temperature');
legend('Data Points', 'Curve Fit');
grid on;

% Define matrices
A = [1 2 3; 4 5 6; 7 8 9];
B = [9 8 7; 6 5 4; 3 2 1];

% i. Matrix product
AB = A * B;
