% Scalar multiplication
B2 = 2 * B;
disp('2 * B ='); disp(B2);

% Partial Fraction Decomposition
% 4x^2/((x+1)^2*(x-1)) = A/(x-1) + B/(x+1) + C/(x+1)^2

% Coefficient matrix from equating powers of x
% x^2: A + B     = 4
% x^1: 2A + C    = 0
% x^0: A - B - C = 0

M = [1  1  0;   % coefficients of A, B, C for x^2 terms
     2  0  1;   % coefficients for x^1 terms
     1 -1 -1];  % coefficients for x^0 terms

b = [4; 0; 0];  % right-hand side values

% Solve using backslash operator
result = M \ b;

A = result(1);
B = result(2);
C = result(3);

fprintf('A = %.4f\n', A);
fprintf('B = %.4f\n', B);
fprintf('C = %.4f\n', C);
fprintf('Result: 4x^2/((x+1)^2*(x-1)) = %.0f/(x-1) + %.0f/(x+1) + (%.0f)/(x+1)^2\n', A, B, C);

% System of Linear Equations
% Coefficient matrix
A = [ 3 -2  5 -4  1;
      5 -3  2  1  4;
     -1  6  1 -2  5;
      4 -2  3  5 -6;
      2  4 -3  6 -2];

% Right-hand side
b = [10; 30; 40; 50; 20];

% i. Augmented matrix approach using rref
Aug = [A, b];           % form augmented matrix [A|b]
R = rref(Aug);          % reduced row echelon form
x_rref = R(:, end);     % last column is the solution
disp('Solution via rref:');
disp(x_rref);

% ii. Left division (most common, numerically stable)
x_left = A \ b;
disp('Solution via left division (A\b):');
disp(x_left);

% ii. Right division equivalent for Ax=b
% Ax=b => x = A\b; right division: (b'/A')'
x_right = (b' / A')';
disp('Solution via right division equivalent:');
disp(x_right);

% LU and SVD Decomposition
X = [1 2 3; 4 5 6; 7 8 9];

% --- LU Decomposition ---
[L, U, P] = lu(X);  % P*X = L*U
disp('L (Lower triangular):'); disp(L);
disp('U (Upper triangular):'); disp(U);
disp('P (Permutation):'); disp(P);

% Reconstruct original matrix from LU
X_from_LU = P' * L * U;  % since P*X=L*U => X = P'*L*U
disp('Reconstructed from LU:'); disp(X_from_LU);

% --- SVD Decomposition ---
[U_svd, S, V] = svd(X);
disp('U (left singular vectors):'); disp(U_svd);
disp('S (singular values diagonal):'); disp(S);
disp('V (right singular vectors):'); disp(V);

% Reconstruct original matrix from SVD
X_from_SVD = U_svd * S * V';
disp('Reconstructed from SVD:'); disp(X_from_SVD);

% Eigenvalue and Eigenvector computation
C = [-1  0 -2;
     -1 -3  0;
     -6 -2 -1];

% eig returns: V = eigenvector matrix, D = diagonal eigenvalue matrix
[V, D] = eig(C);

% Extract eigenvalues from diagonal of D
eigenvalues = diag(D);
disp('Eigenvalues:');
disp(eigenvalues);

% Display eigenvectors (each column is one eigenvector)
disp('Eigenvectors (columns):');
disp(V);

% Verify: C*v = lambda*v for first eigenpair
lambda1 = eigenvalues(1);
v1 = V(:,1);
fprintf('Verification C*v1 = lambda1*v1:\n');
disp(C * v1);        % should equal lambda1 * v1
disp(lambda1 * v1);

