% Save this as powerfit.m
function [b, m] = powerfit(x, y)
    % Fits data to power function y = b * x^m
    % Uses log-log linearization: log(y) = m*log(x) + log(b)

    X = log(x);   % log of x data
    Y = log(y);   % log of y data

    % First-order polynomial fit on log-log data
    coeffs = polyfit(X, Y, 1);
    m = coeffs(1);          % slope = m
    b = exp(coeffs(2));     % intercept = log(b), so b = e^intercept
end

% ---- Main script ----
% Data points
x_data = [0.5, 2.4, 3.2, 4.9, 6.5, 7.8];
y_data = [0.8, 9.3, 37.9, 68.2, 155, 198];

% Fit using powerfit function
[b, m] = powerfit(x_data, y_data);
fprintf('Fitted: b = %.4f, m = %.4f\n', b, m);
fprintf('Equation: y = %.4f * x^%.4f\n', b, m);

% Generate smooth curve
x_fit = linspace(min(x_data), max(x_data), 200);
y_fit = b .* x_fit.^m;

% Plot
figure;
plot(x_data, y_data, 'ro', 'MarkerSize', 8, 'LineWidth', 2); % data markers
hold on;
plot(x_fit, y_fit, 'b-', 'LineWidth', 2);  % fitted curve
xlabel('x');
ylabel('y');
title(sprintf('Power Fit: y = %.3f * x^{%.3f}', b, m));
legend('Data Points', 'Power Fit Curve', 'Location', 'northwest');
