A = [1 2 3 5; 5 3 2 2];

% i. flip — reverses rows (dim=1 default for 2D matrix)
disp('flip(A) =');
disp(flip(A));
% Output: [5 3 2 2
%          1 2 3 5]

% ii. sort — sorts each column ascending
disp('sort(A) =');
disp(sort(A));
% Output: [1 2 2 2; 5 3 3 5]

% iii. A(0:6) = 9 — this will cause an ERROR
% MATLAB indexing starts at 1, not 0
% Uncommenting below will produce: 'index must be a positive integer'
% A(0:6) = 9;

% Water volume in tank
% Ask user to enter height h
h = input('Enter the water height h (in meters): ');

% Calculate volume based on height
if h >= 0 && h <= 19
    % Cylindrical section
    V = pi * 12.5^2 * h;
elseif h > 19 && h <= 33
    % Cylinder base + cone section
    r_h = 12.5 + (10.5/14) * (h - 19);  % radius at height h
    V_cyl = pi * 12.5^2 * 19;            % full cylinder volume
    V_cone = (1/3) * pi * (h - 19) * (12.5^2 + 12.5*r_h + r_h^2); % cone
    V = V_cyl + V_cone;
else
    % Invalid height
    fprintf('Invalid height. h must be between 0 and 33 m.\n');
    V = NaN;
end

% Display result
if ~isnan(V)
    fprintf('Volume of water = %.4f m^3\n', V);
end

% Calculate e^x using Taylor series
x = 1.5;         % given value
n_terms = 20;    % number of terms

result = 0;      % initialize sum to 0

for k = 0:(n_terms - 1)
    term = x^k / factorial(k);  % compute k-th term
    result = result + term;      % add to running sum
end

fprintf('e^1.5 using 20 terms = %.10f\n', result);
fprintf('Exact value exp(1.5) = %.10f\n', exp(1.5));
fprintf('Error = %.2e\n', abs(result - exp(1.5)));

