% Save this function in a file named: myfunc_r.m
function r = myfunc_r(theta)
    % Compute r = 3*sin(3*cos(0.5*theta))
    % theta can be a scalar or vector
    r = 3 .* sin(3 .* cos(0.5 .* theta));
end

% ---- Main script (save separately or run in command window) ----

% i. Evaluate at specific points
theta1 = pi/6;
theta2 = 3*pi/6;
fprintf('r(pi/6)    = %.4f\n', myfunc_r(theta1));
fprintf('r(3pi/6)   = %.4f\n', myfunc_r(theta2));

% ii. Polar plot from 0 to 4*pi
theta = linspace(0, 4*pi, 1000);
r = myfunc_r(theta);

figure;
polarplot(theta, r, 'b-', 'LineWidth', 1.5);
title('Polar plot of r(\theta) = 3 sin(3 cos(0.5\theta))');
